HANDLERS = {"billing": refund_flow, "bug": eng_queue, "other": human_queue}

def route(ticket):
    raw = classify(ticket).lower()
    for label in HANDLERS:
        if label in raw:
            return HANDLERS[label](ticket)
    return HANDLERS["other"](ticket)

def with_retry(p, detect):
    return p + (1 - p) * detect * p

print(round(with_retry(0.8, 1.0), 2), round(with_retry(0.8, 0.25), 2))

def review(material):
    plan = json.loads(ask(f"Plan subtasks for:\n{material}", output_format=PLAN_SCHEMA))
    with ThreadPoolExecutor() as pool:
        results = list(pool.map(run_worker, plan["subtasks"]))
    return ask("Synthesize:\n" + "\n".join(results))
